#include <bits/stdc++.h>
using namespace std;

#define MOD 998244353
#define ff first
#define ss second

typedef long long ll;

ll power(ll a, ll b) {
    ll res = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) {
            res = (res * a) % MOD;
            b--;
        }
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

ll fermat_inv(ll y) {
    return power(y, MOD - 2);
}

ll custom_gcd(ll a, ll b) {
    return (b == 0) ? a : custom_gcd(b, a % b);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll t = 1;
    while (t--) {
        ll n;
        cin >> n;

        ll a1, a2, a3;
        ll b1, b2, b3;
        cin >> a1 >> a2 >> a3 >> b1 >> b2 >> b3;

        ll m2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
        ll m1 = max(a1 + b2, max(a2 + b3, a3 + b1)) - n;
        m1 = max(m1, 0LL);

        cout << m1 << " " << m2 << "\n";
    }

    return 0;
}

